// Rebuilds the third-party browser bundles in vendor/ from the exact versions
// pinned in package.json. The site has no build step, so these files are
// committed. Run `npm run vendor` after changing a pinned version.
import { build } from 'esbuild';
import { mkdir, readFile, writeFile } from 'node:fs/promises';

const pkg = JSON.parse(await readFile(new URL('../node_modules/@supabase/supabase-js/package.json', import.meta.url)));
const result = await build({
  stdin: { contents: "export { createClient } from '@supabase/supabase-js';", resolveDir: process.cwd() },
  bundle: true,
  format: 'esm',
  platform: 'browser',
  target: 'es2022',
  minify: true,
  legalComments: 'none',
  write: false,
});
const banner = `/*! @supabase/supabase-js ${pkg.version} | MIT License | https://github.com/supabase/supabase-js | Generated by scripts/vendor.mjs; do not edit. */\n`;
await writeFile(new URL('../vendor/supabase-js.mjs', import.meta.url), banner + result.outputFiles[0].text);
console.log(`vendor/supabase-js.mjs: @supabase/supabase-js ${pkg.version}`);

await mkdir(new URL('../vendor/tesseract/', import.meta.url), { recursive: true });
// Tesseract's page-side wrapper and worker script run from the vault's origin.
// The WASM core and English model stay on jsDelivr (see vendor/README.md).
const tesseract = JSON.parse(await readFile(new URL('../node_modules/tesseract.js/package.json', import.meta.url)));
for (const file of ['tesseract.esm.min.js', 'worker.min.js']) {
  const source = await readFile(new URL(`../node_modules/tesseract.js/dist/${file}`, import.meta.url), 'utf8');
  const body = source.replace(/\n?\/\/# sourceMappingURL=\S+\s*$/, '\n');
  const header = `/*! tesseract.js ${tesseract.version} | Apache-2.0 License | https://github.com/naptha/tesseract.js | Generated by scripts/vendor.mjs; do not edit. */\n`;
  await writeFile(new URL(`../vendor/tesseract/${file}`, import.meta.url), header + body);
  console.log(`vendor/tesseract/${file}: tesseract.js ${tesseract.version}`);
}
